import{_ as t,o as s,c as e,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const P=JSON.parse('{"title":"BGP / OSPF 路由","description":"","frontmatter":{},"headers":[],"relativePath":"networking/ip/bgp-ospf.md","filePath":"networking/ip/bgp-ospf.md","lastUpdated":1788475713000}'),n={name:"networking/ip/bgp-ospf.md"};function r(l,a,o,d,p,h){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="bgp-ospf-路由" tabindex="-1">BGP / OSPF 路由 <a class="header-anchor" href="#bgp-ospf-路由" aria-label="Permalink to &quot;BGP / OSPF 路由&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>OSPF 是企业/AS 内部的路由协议（IGP），BGP 是互联网之间的路由协议（EGP）。两者解决的问题相似——把包送到目的网段——但抽象层次、可扩展性、强调路径选择 vs metric 的策略完全不同。</p><h2 id="ospf" tabindex="-1">OSPF <a class="header-anchor" href="#ospf" aria-label="Permalink to &quot;OSPF&quot;">​</a></h2><h3 id="link-state" tabindex="-1">Link-State <a class="header-anchor" href="#link-state" aria-label="Permalink to &quot;Link-State&quot;">​</a></h3><p>OSPF 是链路状态协议：</p><ol><li>每个路由器泛洪自己直连链路的&quot;链路通告&quot;（LSA）给整个 area</li><li>每个节点都拿到完整拓扑（LSDB）</li><li>全区域同步 LSDB → 一致性</li><li>节点本地跑 Dijkstra 算最短路径</li><li>计算 ECMP（等价多路径）</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   +-----------LSA-----------+</span></span>
<span class="line"><span>   v                          ^</span></span>
<span class="line"><span>router_a 相当于  LSDB 同步 router_b</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Dijkstra → SPF tree → 路由表</span></span></code></pre></div><p>每个 LSA 还要承载：链路代价、可用 IP 等元数据。开销从 1 起步，最大 65535（24 比特）。</p><h3 id="area-分层" tabindex="-1">Area 分层 <a class="header-anchor" href="#area-分层" aria-label="Permalink to &quot;Area 分层&quot;">​</a></h3><p>OSPF 用多 area 减小 LSDB 与 Dijkstra 规模：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            Area 0 (Backbone)</span></span>
<span class="line"><span>              ┃  ┃  ┃</span></span>
<span class="line"><span>              │  │  │</span></span>
<span class="line"><span>        Area 1  Area 2  Area 3 (分别是与 Backbone 相连)</span></span></code></pre></div><ul><li>Area 0 是 backbone，所有 area 必须与 area 0 有连接或通过 virtual-link 临时桥接</li><li>ABR（Area Border Router）汇总 area 间 LSA，避免把详细 LSDB 跨 area 传播</li><li>ASBR（Autonomous System Border Router）把外部路由灌入 OSPF</li></ul><h3 id="lsa-类型" tabindex="-1">LSA 类型 <a class="header-anchor" href="#lsa-类型" aria-label="Permalink to &quot;LSA 类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>用途</th></tr></thead><tbody><tr><td>1</td><td>Router-LSA</td><td>节点直连链路（本 area 内传播）</td></tr><tr><td>2</td><td>Network-LSA</td><td>广播段子网（DR 通告）</td></tr><tr><td>3</td><td>Summary-LSA</td><td>ABR 宣告跨 area 前缀</td></tr><tr><td>4</td><td>ASBR-summary</td><td>跨 area 到 ASBR 的路径</td></tr><tr><td>5</td><td>AS-external-LSA</td><td>外部路由</td></tr><tr><td>7</td><td>NSSA External LSA</td><td>NSSA 内特殊外部</td></tr></tbody></table><h3 id="ospf-cost-极限" tabindex="-1">OSPF cost 极限 <a class="header-anchor" href="#ospf-cost-极限" aria-label="Permalink to &quot;OSPF cost 极限&quot;">​</a></h3><p>默认 cost = <code>100 / bandwidth(Mbps)</code>：1Gbps cost=1；10Gbps cost=1（实际仍 floor 到 1）。<strong>操作员手工调 cost</strong> 控制路径偏好。</p><div class="language-cisco vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cisco</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">! Cisco IOS 配置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">interface FastEthernet0/0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bandwidth 1000          ! 报 1Gbps</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ip ospf cost 5          ! 改 SPF 选路权重</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>OSPF 实际选路 metric 单调到 1M 已经饱和（多 1G 链路 cost=1 都视为等价）→ ECMP 多路径不会因 metric 略偏好。只能手工分 interface tweak cost 让上层路径有差异。</p></div><hr><h2 id="is-is-与-ospf" tabindex="-1">IS-IS 与 OSPF <a class="header-anchor" href="#is-is-与-ospf" aria-label="Permalink to &quot;IS-IS 与 OSPF&quot;">​</a></h2><p>IS-IS 也链路状态、同 area 内全反映转、Dijkstra 计算。差异：</p><ul><li>IS-IS 在 OSI 协议栈 L2 上跑（CLNS），不直接和 IPv4 强绑</li><li>一个 IS-IS 进程可同时承载 IPv4 + IPv6，OSPF 通常要 v2/v3 分进程</li><li>大型 ISP 更爱 IS-IS，扩展性被认为更强（数百到数千节点 LSDB 单一 area OK）</li></ul><p>主流 ISP（Verizon/Comcast/中国移动/中国电信）核心都用 IS-IS；企业用 OSPF。</p><hr><h2 id="bgp" tabindex="-1">BGP <a class="header-anchor" href="#bgp" aria-label="Permalink to &quot;BGP&quot;">​</a></h2><h3 id="path-vector" tabindex="-1">Path Vector <a class="header-anchor" href="#path-vector" aria-label="Permalink to &quot;Path Vector&quot;">​</a></h3><blockquote><p>距离向量传递&quot;AS_PATH 累积列表&quot;，整个 path 决定可达，不只是 metric。所以叫 Path Vector Protocol。</p></blockquote><p>BGP 基于 TCP port 179。两台路由器直连通过 TCP 179 建立 BGP session，互相宣告 IP prefix + path attributes。</p><h3 id="bgp-message" tabindex="-1">BGP Message <a class="header-anchor" href="#bgp-message" aria-label="Permalink to &quot;BGP Message&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>用途</th></tr></thead><tbody><tr><td>OPEN</td><td>握 hand，版本号、AS、Hold Time (默认 90s)</td></tr><tr><td>KEEPALIVE</td><td>保活</td></tr><tr><td>UPDATE</td><td>宣告/撤回 routes</td></tr><tr><td>NOTIFICATION</td><td>出错关闭 session</td></tr><tr><td>ROUTE-REFRESH</td><td>请求对端重新发</td></tr></tbody></table><h3 id="关键-path-attributes" tabindex="-1">关键 Path Attributes <a class="header-anchor" href="#关键-path-attributes" aria-label="Permalink to &quot;关键 Path Attributes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>选择权</th></tr></thead><tbody><tr><td>ORIGIN</td><td>IGP/EGP/INCOMPLETE</td><td>-</td></tr><tr><td>AS_PATH</td><td>走过的 AS 列表（防环：本 AS 已在 path 则拒）</td><td>选更短</td></tr><tr><td>LOCAL_PREF</td><td>本 AS 进出策略</td><td>选更高</td></tr><tr><td>MED</td><td>跨 AS 退出策略</td><td>选更低</td></tr><tr><td>NEXT_HOP</td><td>下一跳 IP</td><td>-</td></tr><tr><td>COMMUNITY</td><td>标签路由（NO_EXPORT / NO_ADVERTISE 等）</td><td>-</td></tr></tbody></table><h3 id="决策顺序-best-path-algorithm" tabindex="-1">决策顺序（Best Path Algorithm） <a class="header-anchor" href="#决策顺序-best-path-algorithm" aria-label="Permalink to &quot;决策顺序（Best Path Algorithm）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. LOCAL_PREF 高的胜</span></span>
<span class="line"><span>2. AS_PATH 短的胜</span></span>
<span class="line"><span>3. ORIGIN 类型优先级高的胜 (IGP &gt; EGP &gt; INCOMPLETE)</span></span>
<span class="line"><span>4. MED 低的胜（仅当第一 AS 相同才比）</span></span>
<span class="line"><span>5. 到 NEXT_HOP 的 IGP 距离短的胜</span></span>
<span class="line"><span>6. EBGP 路由胜过 IBGP</span></span>
<span class="line"><span>7. OLD 优于 NEW（避免抖动，bandwidth jitter reduction）</span></span>
<span class="line"><span>8. router_id 低胜</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>MRAI (Min Route Advertisement Interval) = 30s</strong>：BGP 默认每 30s 才发 route 广告，限制 churn → 收敛慢。这就是为什么&quot;路由抖动每 30s 你才看到一次&quot;。生产 BGP 改 0 或 5s 加快。</p></div><hr><h2 id="bgp-pluggable-extensions" tabindex="-1">BGP Pluggable Extensions <a class="header-anchor" href="#bgp-pluggable-extensions" aria-label="Permalink to &quot;BGP Pluggable Extensions&quot;">​</a></h2><h3 id="bgp-ls" tabindex="-1">BGP-LS <a class="header-anchor" href="#bgp-ls" aria-label="Permalink to &quot;BGP-LS&quot;">​</a></h3><p>BGP-LS 用 BGP UPDATE 编码链路拓扑分享给集中 SDN 控制面，控制器有了全网拓扑后下发 PCEP/segment routing 流表。SR-MPLS 一类方案就是 <strong>BGP-LS + Path Computation Element 协议 (PCEP)</strong>。</p><h3 id="bgp-evpn" tabindex="-1">BGP EVPN <a class="header-anchor" href="#bgp-evpn" aria-label="Permalink to &quot;BGP EVPN&quot;">​</a></h3><p>数据中心的 BGP EVPN 用 BGP 控制面交换 MAC/IP，把 L3 路由层面统一到一个协议。Spine-Leaf + EVPN 是当前最大型数据中心的标准操作，已被 Cumulus / Arista / Cisco / FRR 全面支持。<strong>替代了 STP + VxLAN + IGMP Snooping + 早期 TRILL</strong>。</p><p>EVPN 的核心：通过 BGP controlplane 同步 MAC/IP，data plane 用 VxLAN 封装，去做&quot;hash 等化负载均衡 + concentration of fail&quot;。</p><h3 id="segment-routing-sr" tabindex="-1">Segment Routing (SR) <a class="header-anchor" href="#segment-routing-sr" aria-label="Permalink to &quot;Segment Routing (SR)&quot;">​</a></h3><p>源路由 in MPLS 标签栈里写&quot;我下一站去 N1, 然后 N2, 然后 N3&quot;，中间路由器只看栈顶标签转发，不用维护每流状态。SR-MPLS / SRv6 (segment in IPv6 Routing Header) 2 种实现。</p><hr><h2 id="选型-ospf-还是-bgp" tabindex="-1">选型：OSPF 还是 BGP？ <a class="header-anchor" href="#选型-ospf-还是-bgp" aria-label="Permalink to &quot;选型：OSPF 还是 BGP？&quot;">​</a></h2><p>答案：两者都要。</p><ul><li><strong>AS 内</strong>（IGP）：OSPF 或 IS-IS，毫秒级收敛，目标最快收敛最少包丢失</li><li><strong>AS 间</strong>（EGP）：BGP，秒分钟级收敛，目标可达性 + policy (不希望被运营商多绕了一条路去付费)</li></ul><p>数据中心 Spine-Leaf 部署 BGP 也是&quot;用 BGP 扮演 IGP&quot;——加 RR (Route Reflector)、宣告自己、local_pref/MET 控制。AWS 风格简洁地利用 BGP 的可扩展性。Meta/JPM/Facebook 数据中心内部都跑 BGP + EVPN，<strong>几乎不用 OSPF</strong>了。</p><h3 id="为啥数据中心不再用-ospf" tabindex="-1">为啥数据中心不再用 OSPF? <a class="header-anchor" href="#为啥数据中心不再用-ospf" aria-label="Permalink to &quot;为啥数据中心不再用 OSPF?&quot;">​</a></h3><ul><li>OSPF area 0 LSDB 同步在 large spine-leaf 网里每次拓扑变化都触发 SPF 计算 → ~1 秒内计算量爆炸</li><li>数据中心 spine-leaf 全 ECMP, BGP naturally 提供，OSPF 需要 tweak</li><li>EVPN + VxLAN 需要 L2 over L3 传播 MAC/IP，BGP EVPN 是事实标准，OSPF 没有</li></ul><hr><h2 id="收敛时间对比" tabindex="-1">收敛时间对比 <a class="header-anchor" href="#收敛时间对比" aria-label="Permalink to &quot;收敛时间对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>健康→故障检测</th><th>收敛时间</th></tr></thead><tbody><tr><td>OSPF 默认</td><td>Hello Interval 10s Dead 40s</td><td>几秒到秒</td></tr><tr><td>OSPF BFD</td><td>50ms 探测</td><td>30ms-1s</td></tr><tr><td>BGP 默认</td><td>Hold Time 90s</td><td>几秒到几十秒</td></tr><tr><td>BGP+BFD</td><td>50ms-300ms 探测 + Connected + 退避</td><td>1s-2s</td></tr></tbody></table><p><strong>BFD (Bidirectional Forwarding Detection)</strong> 是任意链路协议都可叠加邻居存活探测，与 BFD 重叠的是 <strong>GR (Graceful Restart) / NSR (Non-Stop Routing)</strong>：路由器主控 failover 时让邻居保持会话不撕裂。</p><hr><h2 id="实战-调-ospf-切换" tabindex="-1">实战：调 OSPF 切换 <a class="header-anchor" href="#实战-调-ospf-切换" aria-label="Permalink to &quot;实战：调 OSPF 切换&quot;">​</a></h2><div class="language-cisco vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cisco</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">! 路由器 1 关闭链路 -&gt; 路由器 2 在 40s 内才会发现 OSPF dead</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">! 启用 BFD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">router ospf 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bfd all-interfaces</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">! 调稀疏 SPF throttle (怕 churn 不怕慢)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">router ospf 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timers throttle spf 10 100 200</span></span></code></pre></div><p>(0ms initial, 100ms wait-min, 200ms wait-max)</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux 看 OSPF 邻居 (FRR/Quagga)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vtysh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;show ip ospf neighbor&#39;</span></span></code></pre></div><hr><h2 id="真实生产事故参考" tabindex="-1">真实生产事故参考 <a class="header-anchor" href="#真实生产事故参考" aria-label="Permalink to &quot;真实生产事故参考&quot;">​</a></h2><ol><li><strong>Pakistan Telecom 2008</strong>：误把 YouTube 的 /24 prefix 注入 BGP AS_PATH 空，全球 BGP 路由器向 YouTube 改路到巴基斯坦 → 全球用户 2 小时进不了 YouTube。<strong>教训</strong>：BGP 没有 RPKI ROA 强制 RPKI。RPKI 现已广泛部署，过滤掉 ROA 不符合的 routes。</li><li><strong>YouTube 2017 雪球</strong>: 某次 BGP 配置 typo 引起广泛 churn + RPKI 清理 + 链路抖动 → 全球 BGP 路由表 几秒钟抖动湿式 churn 让所有 ISP 同时 recalculating best path。<strong>修复</strong>：BGP add-path + BGP-LS 监视收敛速率，远离 churn 重置事件。</li><li><strong>Cloudflare 2019 6/24</strong>：配置变更使 BGP 撤回 RPKI 失效前缀 → 部分全球用户连不上 → 27 分钟。<strong>修复</strong>：BGP 配置变更通过 dry-run emulator 测试 + RPKI 自动化校验。</li></ol><hr><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ol><li>OSPF Link-State Dijkstra，可扩展性限定在 area 数 (一般每 area ~200 节点)</li><li>BGP Path-Vector policy，可承载 ~1.1M+ v4 前缀</li><li>BGP 不快、BFD 帮加快 + GR/NSR 帮 failover 不撕裂</li><li>BGP EVPN 已成新一代 DC L3 over leaf 标准；OSPF 在 DC 退潮</li><li>RPKI + BGP-LS + segment routing 是 2020 后路由协议演化的三大方向</li></ol><p>下一节 → <a href="./nat">NAT 与 conntrack</a></p>`,68)])])}const u=t(n,[["render",r]]);export{P as __pageData,u as default};
